import java.sql.*; public class Main{static void transfer(Connection c,long from,long to)throws SQLException{boolean old=c.getAutoCommit();c.setAutoCommit(false);try(PreparedStatement d=c.prepareStatement("UPDATE wallet SET balance=balance-500 WHERE id=? AND balance>=500");PreparedStatement cr=c.prepareStatement("UPDATE wallet SET balance=balance+500 WHERE id=?")){d.setLong(1,from);if(d.executeUpdate()!=1)throw new SQLException("Insufficient funds");cr.setLong(1,to);if(cr.executeUpdate()!=1)throw new SQLException("Wallet missing");c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}}public static void main(String[]a){System.out.println("Transfer: debit and credit in one transaction; rollback on any failure.");System.out.println("Login uses PreparedStatement placeholders for username and password hash.");}}